import heapq

def solve(a, k):
    # Skeleton for: Kth largest element in a stream of running integers
    heap = []
    for x in a:
        heapq.heappush(heap, x)  # min-heap; adapt for max-heap via -x
        if len(heap) > k:
            heapq.heappop(heap)
    return list(heap)
